# Let me do one more comprehensive search in the JSON data for any exchange rate info
import json

# Read the JSON file and search for any relevant exchange data
with open('/app/resources/treasury_bulletin_1960_01.json', 'r') as f:
    content = json.load(f)

# Look for any fields related to exchange or CAD or Canada
def search_recursive(obj, path=""):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if any(term in str(k).lower() for term in ['exchange', 'cad', 'canada', 'canadian', 'usd']):
                results.append((k, v))
            results.extend(search_recursive(v, path + "." + str(k)))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(search_recursive(item, path + f"[{i}]"))
    return results

results = search_recursive(content)
print("Found relevant data in JSON:")
for r in results[:30]:
    print(f"  {r}")
